{"query":"agreement verdict of a claim against a commit: corroborated neutral contradicted","repo_root":"/home/voxmastery/Desktop/cli","commit":"8a3362fe39c8035de31e06e59f4a643b2ae0dfe3","tree":"fa6580b27052a84e5545206395aa95db6f1027b2","profile":"full","results":[{"rank":1,"score":47.3167,"file_path":"recall/src/agreement.rs","start_line":26,"end_line":118,"focus_line":36,"snippet_start_line":28,"snippet_end_line":118,"symbol_start_line":28,"symbol_end_line":118,"language":"Rust","kind":"function","symbol_id":"local/cli:Rust:recall/src/agreement.rs:function:agreement","symbol_name":"agreement","qualified_name":"agreement","signature":"pub fn agreement(claim: &str, cp: &Checkpoint, g: &GraphReach) -> (Agree, String)","signals":["path","body","symbol-name","signature","graph:callers","complete-symbol"],"snippet":"pub fn agreement(claim: &str, cp: &Checkpoint, g: &GraphReach) -> (Agree, String) {
    let low = claim.to_lowercase();

    // 1. Scope: claim asserts isolation, Graph says the blast radius escapes.
    if ISOLATION.iter().any(|w| low.contains(w)) {
        let reach = g.escapes(&cp.files);
        if !reach.is_empty() {
            return (
                Agree::Contradicted,
                format!(
                    "claims isolation; Graph reach escapes to {} ({})",
                    reach.len(),
                    reach.join(", ")
                ),
            );
        }
    }

    // 2. File: claim names a path the commit never touched. URL segments are
    //    not paths: a pasted link must not read as an untouched file.
    let claim_terms = terms(claim);
    for t in claim_terms
        .iter()
        .filter(|t| (t.contains('/') || t.ends_with(".go")) && !looks_like_url(t))
    {
        if !cp
            .files
            .iter()
            .any(|f| f.to_lowercase().contains(t.as_str()))
        {
            return (
                Agree::Contradicted,
                format!("references {t} which this commit did not touch"),
            );
        }
    }

    // 3. Polarity flip: same topic, opposite action. Conventional-commit
    //    prefixes carry polarity the verb list misses.
    let pc = polarity(claim);
    let mut pm = polarity(&cp.commit_message);
    if pm == 0 {
        let m = cp.commit_message.to_lowercase();
        if m.starts_with("feat") || m.starts_with("fix") || m.starts_with("perf") {
            pm = 1;
        } else if m.starts_with("revert") {
            pm = -1;
        }
    }
    let commit_terms = terms(&cp.commit_message);
    if pc != 0 && pm != 0 && pc != pm && claim_terms.intersection(&commit_terms).count() >= 1 {
        return (
            Agree::Contradicted,
            "action polarity opposes the commit".into(),
        );
    }

    // 4. M1 identifier anchor: a code-shaped token the diff never contains.
    if let Some(ident) = missing_identifier(claim, cp) {
        return (
            Agree::Contradicted,
            format!("names {ident}, which the change does not contain"),
        );
    }

    // 5. Lexical agreement with what the commit says it did.
    let shared = claim_terms.intersection(&commit_terms).count();
    if shared >= LEXICAL_MIN_SHARED {
        return (
            Agree::Corroborated,
            format!("{shared} terms match commit subject"),
        );
    }

    // 6. Character 4-gram cosine against the diff and file names.
    let corpus = format!(
        "{} {} {}",
        cp.commit_message,
        cp.files.join(" "),
        cp.diff.join(" ")
    );
    let sim = cosine(&ngrams(claim), &ngrams(&corpus));
    if sim > NGRAM_THRESHOLD {
        return (
            Agree::Corroborated,
            format!("4-gram cosine {sim:.3} with the change"),
        );
    }

    (Agree::Neutral, "no overlap with commit subject".into())
}"},{"rank":2,"score":44.3563,"file_path":"recall/src/rank.rs","start_line":54,"end_line":107,"focus_line":68,"snippet_start_line":54,"snippet_end_line":107,"symbol_start_line":54,"symbol_end_line":107,"language":"Rust","kind":"function","symbol_id":"local/cli:Rust:recall/src/rank.rs:function:rerank","symbol_name":"rerank","qualified_name":"rerank","signature":"pub fn rerank(recalls: &[RecallResult], cps: &[Checkpoint], g: &GraphReach) -> Vec<Ranked>","signals":["body","signature","complete-symbol"],"snippet":"pub fn rerank(recalls: &[RecallResult], cps: &[Checkpoint], g: &GraphReach) -> Vec<Ranked> {
    let by_sha: HashMap<&str, &Checkpoint> =
        cps.iter().map(|c| (c.commit_sha.as_str(), c)).collect();

    let mut out: Vec<Ranked> = recalls
        .iter()
        .map(|r| {
            let kind = source_kind(&r.episode.provenance);
            let mut ev = vec![Evidence::new(kind, 1.0)];
            let sha = commit_of(&r.episode.context);
            let cp = sha.as_deref().and_then(|k| by_sha.get(k).copied());
            let backed_by = cp.map(|c| format!("{} {}", c.commit_sha, c.commit_message));
            let (verdict, why) = match cp {
                Some(cp) if kind != SourceKind::Verified => agreement(&r.episode.content, cp, g),
                Some(_) => (Agree::Corroborated, "is the commit record".into()),
                None => (Agree::Neutral, "no commit context".into()),
            };
            match verdict {
                // Earned corroboration: an independent verified source.
                Agree::Corroborated if kind != SourceKind::Verified => {
                    ev.push(Evidence::new(SourceKind::Verified, 1.0))
                }
                // Refuted by the ledger: the claim is evidence against itself.
                Agree::Contradicted => ev.push(Evidence::new(SourceKind::Unknown, 0.15)),
                _ => {}
            }
            let mut confidence = recall_confidence(&ev);
            if verdict == Agree::Contradicted {
                confidence *= CONTRADICTION_PENALTY;
            }
            let scored = r.activation * activation_multiplier(confidence);
            Ranked {
                raw: r.activation,
                scored,
                confidence,
                tier: tier(kind).to_string(),
                verdict,
                why,
                backed_by,
                commit: sha,
                text: r.episode.content.replace('\n', " "),
                context: r.episode.context.clone(),
            }
        })
        .collect();
    out.sort_by(|a, b| {
        b.scored
            .partial_cmp(&a.scored)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    let mut seen = HashSet::new();
    out.retain(|r| seen.insert(r.text.clone()));
    out
}"},{"rank":3,"score":44.3463,"file_path":"recall/src/rank.rs","start_line":40,"end_line":43,"focus_line":40,"snippet_start_line":40,"snippet_end_line":43,"symbol_start_line":40,"symbol_end_line":43,"language":"Rust","kind":"function","symbol_id":"local/cli:Rust:recall/src/rank.rs:function:commit_of","symbol_name":"commit_of","qualified_name":"commit_of","signature":"pub fn commit_of(ctx: &str) -> Option<String>","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"pub fn commit_of(ctx: &str) -> Option<String> {
